import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int r = sc.nextInt(), c = sc.nextInt();
            int[][] mat = new int[r][c];
            for (int i = 0; i < r; i++)
                for (int j = 0; j < c; j++)
                    mat[i][j] = sc.nextInt();
            for (int j = 0; j < c; j++) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < r; i++) {
                    if (i > 0) sb.append(" ");
                    sb.append(mat[i][j]);
                }
                System.out.println(sb.toString());
            }
        }
    }
}

