code.JavaScript:
const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length >= 2) {
        const R = toks[0], C = toks[1];
        let idx = 2;
        const mat = [];
        for (let r = 0; r < R; r++) {
            mat.push(toks.slice(idx, idx + C));
            idx += C;
        }
        for (let c = 0; c < C; c++) {
            const row = [];
            for (let r = 0; r < R; r++) row.push(mat[r][c]);
            console.log(row.join(" "));
        }
    }
}
main();

